function hotelOne(PDO $pdo,string $sql,array $args=[]): ?array {
    if(!str_starts_with($sql,'SELECT '))hotelFail('read_only_query_required');
    $s=$pdo->prepare($sql);$s->execute($args);$row=$s->fetch(PDO::FETCH_ASSOC);
    if($s->fetch(PDO::FETCH_ASSOC)!==false)hotelFail('ambiguous_readback');$s->closeCursor();return $row===false?null:$row;
}

function hotelAll(PDO $pdo,string $sql,array $args,int $limit): array {
    if(!str_starts_with($sql,'SELECT '))hotelFail('read_only_query_required');
    $s=$pdo->prepare($sql);$s->execute($args);$rows=[];
    try{while(($row=$s->fetch(PDO::FETCH_ASSOC))!==false){if(count($rows)>=$limit)hotelFail('readback_bounds_unconfirmed');$rows[]=$row;}}
    finally{$s->closeCursor();}return $rows;
}
function hotelHash(string $value): string {
    if(!preg_match('/\A[a-f0-9]{64}\z/D',$value))hotelFail('required_pin_unfilled');return $value;
}
function hotelPinnedObject(mixed $value,string $sha): array {
    if(!is_array($value)||!hash_equals(hotelHash($sha),hash('sha256',HotelServerInputs::json($value))))hotelFail('public_payload_pin_unconfirmed');return $value;
}
function hotelRuntime(string $app,string $sha,string $campaign,string $bootstrap): string {
    $path=dirname($app).'/max-search-bot-hotel-server/runtime.json';$raw=hotelRead($path,65536,null,$sha);
    $loaded=HotelServerRuntimeConfig::load($app);
    if(!is_array($loaded)||($loaded['configuration_sha256']??null)!==$sha||($loaded['campaign_id']??null)!==$campaign
        ||($loaded['bootstrap_sha256']??null)!==$bootstrap
        ||HotelServerInputs::json($loaded['flags']??null)!==HotelServerInputs::json(['enabled'=>true,'dispatch_allowed'=>true,'replacement_dispatch_allowed'=>true]))
        hotelFail('runtime_identity_unconfirmed');return $raw;
}
/** Fixed predecessor only. Reads small canonical new records, never exports legacy history. */
function hotelPredecessor(PDO $pdo,bool $enabled,string $laneOwner,string $retainedBaseline): array {
    $lane=hotelOne($pdo,"SELECT queue_id FROM hotel_work_lane WHERE lane_key='HOTEL'");
    if($lane===null||$lane['queue_id']!==$laneOwner)hotelFail('hotel_lane_owner_unconfirmed');
