    if($c===null||$c['state']!=='complete'||((int)$c['enabled']===1)!==$enabled||(int)$c['stage_cursor']!==4
        ||(int)$c['new_accepted']!==4||(int)$c['historical_accepted']!==19||$c['bootstrap_sha256']!==HOTEL_OLD_BOOTSTRAP
        ||$c['baseline_sha256']!==HOTEL_OLD_BASELINE||$c['inputs_sha256']!==HOTEL_OLD_INPUTS)hotelFail('predecessor_CAS');
    $counts=[];
    foreach(['receipts'=>'hotel_server_receipts','records'=>'hotel_server_records','baselines'=>'hotel_server_baselines',
        'candidates'=>'hotel_server_candidates','reviews'=>'hotel_server_reviews','attempts'=>'hotel_server_attempts','outbox'=>'hotel_server_outbox'] as $name=>$table){
        $row=hotelOne($pdo,'SELECT COUNT(*) AS n FROM '.$table.' WHERE campaign_id=?',[HOTEL_PREDECESSOR]);$counts[$name]=(int)$row['n'];
    }
    if($counts!==['receipts'=>4,'records'=>4,'baselines'=>5,'candidates'=>4,'reviews'=>4,'attempts'=>8,'outbox'=>8])hotelFail('predecessor_completion_counts_unconfirmed');
    foreach(['hotel_server_attempts'=>'succeeded','hotel_server_outbox'=>'done'] as $table=>$expected){
        $row=hotelOne($pdo,'SELECT COUNT(*) AS n FROM '.$table.' WHERE campaign_id=? AND state<>?',[HOTEL_PREDECESSOR,$expected]);
        if((int)$row['n']!==0)hotelFail('predecessor_unfinished_attempt_or_outbox');
    }
    $receipts=hotelAll($pdo,'SELECT stage_index,receipt_sha256,receipt_bytes FROM hotel_server_receipts WHERE campaign_id=? ORDER BY stage_index',[HOTEL_PREDECESSOR],4);
    $receiptRefs=[];$decoded=[];$parent=$retainedBaseline;
    foreach($receipts as $index=>$row){
        if((int)$row['stage_index']!==$index||!is_string($row['receipt_bytes'])||strlen($row['receipt_bytes'])>65536
            ||!hash_equals(hotelHash($row['receipt_sha256']),hash('sha256',$row['receipt_bytes'])))hotelFail('predecessor_receipt_unconfirmed');
        $r=hotelJson($row['receipt_bytes']);
        if(($r['schema']??null)!=='hotel-server-acceptance-v1'||($r['campaign_id']??null)!==HOTEL_PREDECESSOR
            ||($r['stage_index']??null)!==$index||($r['previous_baseline_sha256']??null)!==$parent
            ||($r['inputs_sha256']??null)!==HOTEL_OLD_INPUTS||($r['new_acceptance_credit']??null)!==1
            ||HotelServerInputs::json($r)!==$row['receipt_bytes'])hotelFail('predecessor_receipt_chain_unconfirmed');
        $parent=hotelHash($r['baseline_sha256']??'');$decoded[$index]=$r;
        $receiptRefs[]=['stage_index'=>$index,'receipt_sha256'=>$row['receipt_sha256']];
    }
    if($parent!==HOTEL_OLD_BASELINE)hotelFail('predecessor_terminal_baseline_unconfirmed');
    $rows=hotelAll($pdo,'SELECT r.semantic_key,r.campaign_id,r.candidate_sha256,r.record_bytes,c.stage_index FROM hotel_server_records r JOIN hotel_server_candidates c ON c.campaign_id=r.campaign_id AND c.candidate_sha256=r.candidate_sha256 WHERE r.campaign_id=? ORDER BY r.semantic_key',[HOTEL_PREDECESSOR],4);
    if(count($rows)!==4)hotelFail('predecessor_saved_records_unconfirmed');$refs=[];$seen=[];
    foreach($rows as $row){
        $stage=(int)$row['stage_index'];$r=$decoded[$stage]??null;
        if($r===null||$row['candidate_sha256']!==$r['candidate_sha256']||!is_string($row['record_bytes'])
            ||strlen($row['record_bytes'])<1||strlen($row['record_bytes'])>1048576||isset($seen[$row['semantic_key']]))hotelFail('predecessor_record_lineage_unconfirmed');
        $record=hotelJson($row['record_bytes']);
        if(HotelServerInputs::key($record['scope']??[])!==$row['semantic_key']||HotelServerInputs::json($record)!==$row['record_bytes'])hotelFail('predecessor_canonical_record_unconfirmed');
        $seen[$row['semantic_key']]=true;$refs[]=['semantic_key'=>$row['semantic_key'],'campaign_id'=>HOTEL_PREDECESSOR,
            'stage_index'=>$stage,'candidate_sha256'=>$row['candidate_sha256'],'receipt_sha256'=>$receiptRefs[$stage]['receipt_sha256'],
            'record_sha256'=>hash('sha256',$row['record_bytes'])];
    }
    return ['counts'=>$counts,'seed'=>['schema'=>'hotel-server-continuation-seed-v1','retained_baseline_sha256'=>$retainedBaseline,
        'predecessor'=>['campaign_id'=>HOTEL_PREDECESSOR,'bootstrap_sha256'=>HOTEL_OLD_BOOTSTRAP,'baseline_sha256'=>HOTEL_OLD_BASELINE,
            'inputs_sha256'=>HOTEL_OLD_INPUTS,'receipts'=>$receiptRefs],'records'=>$refs]];
}
function hotelEnabled(PDO $pdo,?string $expected): void {
    $rows=hotelAll($pdo,'SELECT campaign_id FROM hotel_server_campaigns WHERE enabled=1',[],2);
    if($expected===null?count($rows)!==0:(count($rows)!==1||$rows[0]['campaign_id']!==$expected))hotelFail('enabled_campaign_set_unconfirmed');
