    hotelKeys($policy,['budget_attestation_sha256','input_token_ceiling','max_scopes','max_source_age_seconds','model','principals',
        'profile_sha256','request_byte_ceiling','reserved_micros_minimum','source_mode','valid_until']);
    hotelKeys($policy['principals']??[],['producer','reviewer']);
    foreach($plan['limits'] as $value)if(!is_int($value)||$value<1||$value>2000000000)hotelFail('bounded_plan_required');
    $profile=ManagerDraftClient::hotelRuntimeProfile();
