        ||($profile['model']??null)!=='gpt-6.1-sol'||($profile['max_output_tokens']??null)!==2200||($profile['store']??null)!==false
        ||($policy['model']??null)!=='gpt-6.1-sol'||($policy['profile_sha256']??null)!==HOTEL_PROFILE_SHA
        ||$policy['max_scopes']!==4||$policy['request_byte_ceiling']>32768
