        hotelRuntime($app,HOTEL_OLD_RUNTIME,HOTEL_PREDECESSOR,HOTEL_OLD_BOOTSTRAP);return true;
    };
    $report+=['predecessor_bootstrap_sha256'=>HOTEL_OLD_BOOTSTRAP,'predecessor_baseline_sha256'=>HOTEL_OLD_BASELINE,
        'public_payload_sha256'=>HOTEL_PAYLOAD_SHA,'inputs_sha256'=>$package['inputs_sha256'],'bootstrap_sha256'=>$bootstrapPin,
        'continuation_seed_sha256'=>$seedSha,'retained_admission'=>$package['retained_admission'],'expected_stages'=>4,'expected_scopes'=>16,
        'maximum_calls'=>8,'accepted_facts_sha256'=>$oldFactsSha,'accepted_facts_count'=>$oldFactsCount];
    $report['phase']='bootstrap_next';hotelWriteNew($work.'/bootstrap-next.intent.json',HotelServerInputs::json(['operation_id'=>HOTEL_OPERATION,'github_run_id'=>$run,'state'=>'single_invocation_starting']));
    $report['bootstrap_next_invoked']=true;
    $disabled=$cycle->bootstrapNext(HOTEL_PREDECESSOR,HOTEL_OLD_BOOTSTRAP,HOTEL_OLD_BASELINE,HOTEL_CAMPAIGN,$inputs,$plan,$authorizedOld);
    $report['phase']='disabled_readback';
    if(($disabled['campaign_id']??null)!==HOTEL_CAMPAIGN||($disabled['state']??null)!=='disabled'||($disabled['enabled']??null)!==false
        ||($disabled['new_accepted']??null)!==0||($disabled['stage_index']??null)!==0||($disabled['historical_accepted']??null)!==19
        ||($disabled['baseline_sha256']??null)!==$seedSha||($disabled['bootstrap_sha256']??null)!==$bootstrapPin)hotelFail('successor_disabled_readback_unconfirmed');
    hotelEnabled($pdo,null);$after=hotelPredecessor($pdo,false,HOTEL_CAMPAIGN,$originalPackage['pins']['baseline']);
    if(HotelServerInputs::json($after)!==HotelServerInputs::json($before))hotelFail('predecessor_history_changed');
    $new=hotelOne($pdo,'SELECT campaign_id,state,enabled,stage_cursor,new_accepted,bootstrap_sha256,baseline_sha256,inputs_sha256,plan_bytes FROM hotel_server_campaigns WHERE campaign_id=?',[HOTEL_CAMPAIGN]);
    $seed=hotelOne($pdo,'SELECT baseline_sha256,parent_sha256,document_bytes FROM hotel_server_baselines WHERE campaign_id=? AND baseline_sha256=?',[HOTEL_CAMPAIGN,$seedSha]);
    if($new===null||$new['state']!=='disabled'||(int)$new['enabled']!==0||(int)$new['stage_cursor']!==0||(int)$new['new_accepted']!==0
        ||$new['bootstrap_sha256']!==$bootstrapPin||$new['baseline_sha256']!==$seedSha||$new['inputs_sha256']!==$package['inputs_sha256']||$new['plan_bytes']!==$planBytes
        ||$seed===null||$seed['parent_sha256']!==null||$seed['document_bytes']!==$seedBytes||hash('sha256',$seed['document_bytes'])!==$seedSha)
        hotelFail('server_derived_seed_readback_unconfirmed');
